bool PCXHandler::write(const QImage &image)
{
    QDataStream s(device());
    s.setByteOrder(QDataStream::LittleEndian);

    QImage img = image;

    int w = img.width();
    int h = img.height();

//   qDebug() << "Width: " << w;
//   qDebug() << "Height: " << h;
//   qDebug() << "Depth: " << img.depth();
//   qDebug() << "BytesPerLine: " << img.bytesPerLine();
//   qDebug() << "Color Count: " << img.colorCount();

    PCXHEADER header;

    header.Manufacturer = 10;
    header.Version = 5;
    header.Encoding = 1;
    header.XMin = 0;
    header.YMin = 0;
    header.XMax = w - 1;
    header.YMax = h - 1;
    header.HDpi = 300;
    header.YDpi = 300;
    header.Reserved = 0;
    header.PaletteInfo = 1;

    if (img.depth() == 1) {
        writeImage1(img, s, header);
    } else if (img.depth() == 8 && img.colorCount() <= 16) {
        writeImage4(img, s, header);
    } else if (img.depth() == 8) {
        writeImage8(img, s, header);
    } else if (img.depth() == 32) {
        writeImage24(img, s, header);
    }

    return true;
}

